// Utilizing native trait dispatch
pub trait Counter {
    fn get(&self) -> u32;
    fn inc(&mut self);
}

pub struct ConcreteCounter {
    x: u32,
}

impl Counter for ConcreteCounter {
    fn get(&self) -> u32 { self.x }
    fn inc(&mut self) { self.x += 1; }
